/** Native Android views and on-device state. No WebView or website launcher. */
public final class MainActivity extends Activity {
    private static final int GREEN=0xff147d68,INK=0xff183f38,MUTED=0xff536f67,BG=0xfff3f9f4;
    private NativeStore store;
    private NativeApi api;
    private LinearLayout body,nav;
    private TextView status,timerText;
    private String tab="Home";
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private boolean busy=false,running=false;
    private long accumulated=0,startedAt=0;
    private int selectedExercise=0;
    private static final String[] EXERCISES={"Comfortable walking","Chair squat","Wall push-up","Standing march","Glute bridge","Gentle mobility"};
    private static final String[] CUES={"Stand tall and walk at a pace where you can talk.\nStart gently. Slow down or rest whenever needed.","Place a stable chair behind you.\nKeep feet about hip-width apart.\nSit back slowly, touch the chair, then stand with control.","Place hands on a wall at shoulder height.\nStep back slightly. Bend your elbows, then push away gently.\nKeep your body aligned.","Stand near a stable support.\nLift one knee comfortably, lower it, then alternate.\nStay upright and use a steady pace.","Lie on your back with knees bent and feet flat.\nGently lift your hips, keeping shoulders relaxed.\nLower slowly. Avoid arching your lower back.","Move your shoulders and ankles through a comfortable range.\nBreathe normally.\nSkip any movement that causes pain."};
    private final Runnable tick=new Runnable(){public void run(){if(timerText!=null)timerText.setText(time(activeSeconds())+(running?" • active":" • paused"));handler.postDelayed(this,1000);}};

    @Override public void onCreate(Bundle saved) {
        super.onCreate(saved);store=new NativeStore(this);api=new NativeApi(this);
        if(saved!=null){tab=saved.getString("tab","Home");accumulated=saved.getLong("seconds",0);selectedExercise=saved.getInt("exercise",0);}
        buildShell();render();handler.post(tick);
        if(store.signedIn())sync();
    }
    @Override protected void onSaveInstanceState(Bundle out){out.putString("tab",tab);out.putLong("seconds",activeSeconds());out.putInt("exercise",selectedExercise);super.onSaveInstanceState(out);}
    @Override protected void onPause(){pauseTimer();super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);worker.shutdown();super.onDestroy();}
    private void buildShell(){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);
        root.setOnApplyWindowInsetsListener((view,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(b.left,b.top,b.right,b.bottom);}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(20),dp(12),dp(16),0);
        TextView brand=text("NUTRIGUIDE",23,GREEN);brand.setTypeface(null,Typeface.BOLD);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
        Button account=button("Account",()->showAccount(false));header.addView(account);root.addView(header);
        status=text(store.signedIn()?"Your account • cached on this phone":"On-device mode • your data stays on this phone",12,MUTED);status.setPadding(dp(20),dp(4),dp(20),dp(8));status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(6),dp(18),dp(18));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);nav.setPadding(dp(4),dp(4),dp(4),dp(4));root.addView(nav);setContentView(root);buildNav();
    }
    private void buildNav(){nav.removeAllViews();for(String name:new String[]{"Home","Food","Move","Journey","Reports"}){Button b=button(name,()->{tab=name;render();});b.setTextSize(11);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(0,0,0,0);if(!name.equals(tab)){b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffe6f1e9));b.setTextColor(INK);}nav.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));}}
    private void render(){ensureDay();body.removeAllViews();timerText=null;buildNav();switch(tab){case "Food":food();break;case "Move":move();break;case "Journey":journey();break;case "Reports":reports();break;default:home();}}
    private JSONObject state(){return store.snapshot();}
    private JSONObject object(JSONObject s,String key){JSONObject x=s.optJSONObject(key);return x==null?new JSONObject():x;}
    private JSONArray array(JSONObject s,String key){JSONArray a=s.optJSONArray(key);return a==null?new JSONArray():a;}
    private JSONObject json(Object... pairs){JSONObject o=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)o.put((String)pairs[i],pairs[i+1]);}catch(Exception e){throw new IllegalArgumentException(e);}return o;}
    private String day(){return LocalDate.now().toString();}
    private double number(String s){try{return Double.parseDouble(s);}catch(Exception e){return Double.NaN;}}
    private int calories(){JSONObject p=object(state(),"profile");int base=WellnessMath.calories(p.optDouble("age"),p.optDouble("height"),p.optDouble("weight"),p.optString("sex"),p.optDouble("activity"),p.optString("goal"));if(base==0)return 0;double custom=object(object(state(),"ngPersonalSettings"),"targets").optDouble("calories");return Double.isFinite(custom)&&custom>=1200&&custom<=5000?(int)custom:base;}
    private int protein(){if(calories()==0)return 0;JSONObject p=object(state(),"profile");double custom=object(object(state(),"ngPersonalSettings"),"targets").optDouble("protein");return Double.isFinite(custom)&&custom>=20&&custom<=300?(int)custom:WellnessMath.protein(p.optDouble("weight"),p.optString("goal"));}
    private double[] totals(String date){double[] result=new double[5];JSONArray logs=array(state(),"nutritionLog");String[] keys={"cal","p","c","fat","f"};for(int i=0;i<logs.length();i++){JSONObject x=logs.optJSONObject(i);if(x!=null&&date.equals(x.optString("date")))for(int j=0;j<5;j++)result[j]+=x.optDouble(keys[j],0);}if(date.equals(day())){JSONArray extra=array(state(),"proteinItems");for(int i=0;i<extra.length();i++)if(extra.optJSONObject(i)!=null)result[1]+=extra.optJSONObject(i).optDouble("g",0);}return result;}
    private void ensureDay(){
        JSONObject s=state();String previous=s.optString("ngLogDate","");if(day().equals(previous))return;
        if(!previous.isEmpty()){JSONObject stats=object(s,"ngDailyStats");double[] t=totals(previous);try{stats.put(previous,json("steps",s.optInt("steps",0),"water",s.optInt("water",0),"cal",t[0],"p",t[1]));}catch(Exception ignored){}store.put("ngDailyStats",stats);store.put("steps",0);store.put("water",0);store.put("proteinItems",new JSONArray());}
        store.put("ngLogDate",day());
    }
    private void home(){
        heading("A little better, every day.","Your native wellness space • "+day());
        if(calories()==0){card("Start with your own profile","Complete your profile to set calorie and protein targets. New accounts start empty.");addButton("Set up profile",this::profile);}else{double[] t=totals(day());card("Calories remaining",Math.max(0,calories()-(int)Math.round(t[0]))+" kcal\n"+(int)Math.round(t[0])+" of "+calories()+" kcal logged");card("Protein today",fmt(t[1])+" g of "+protein()+" g");ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setProgress((int)Math.min(100,100*t[1]/protein()));body.addView(bar);addButton("Edit profile",this::profile);addButton("Edit daily targets",this::customTargets);}
        JSONObject s=state();card("Movement & water",s.optInt("steps",0)+" steps • "+s.optInt("water",0)+" glasses of water");
        addButton("Add a glass of water",()->{store.put("water",Math.min(30,state().optInt("water",0)+1));render();saved();});
        EditText steps=input("Steps today",String.valueOf(s.optInt("steps",0)),true);addButton("Save steps",()->{double n=number(steps.getText().toString());if(!Double.isFinite(n)||n<0||n>100000||n!=Math.floor(n)){notice("Enter 0–100,000 whole steps.");return;}store.put("steps",(int)n);render();saved();});
        String[] guides={"Fresh-start kid","Hydration cat","Workout duo","Adventure explorer","Panda trainer","Star fitness hero"};int selected=Math.max(0,Math.min(5,s.optInt("selectedGuide",4)));card("Your guide • "+guides[selected],"Build one repeatable habit today. Food and workout suggestions are separate from completed logs.");
        Spinner choice=spinner(guides,selected);addButton("Choose guide",()->{store.put("selectedGuide",choice.getSelectedItemPosition());render();saved();});
        if(store.signedIn())addButton("Sync my account",this::sync);
    }
    private void profile(){
        body.removeAllViews();heading("Your profile","Targets come from your details. Estimates are editable planning values, not medical advice.");JSONObject p=object(state(),"profile");
        EditText age=input("Age",p.optString("age",""),true),height=input("Height (cm)",p.optString("height",""),true),weight=input("Weight (kg)",p.optString("weight",""),true);
        label("Sex used for estimate");Spinner sex=spinner(new String[]{"Male","Female"},p.optString("sex").equals("female")?1:0);
        double[] activities={1.2,1.375,1.55,1.725};int ai=1;for(int i=0;i<activities.length;i++)if(p.optDouble("activity")==activities[i])ai=i;
        label("Activity level");Spinner activity=spinner(new String[]{"Mostly sitting","Lightly active","Moderately active","Very active"},ai);label("Goal");String[] goals={"loss","maintain","gain"};int gi=p.optString("goal").equals("maintain")?1:p.optString("goal").equals("gain")?2:0;Spinner goal=spinner(new String[]{"Lose weight","Maintain weight","Build weight & strength"},gi);
        addButton("Save profile",()->{double a=number(age.getText().toString()),h=number(height.getText().toString()),w=number(weight.getText().toString()),ac=activities[activity.getSelectedItemPosition()];String sx=sex.getSelectedItemPosition()==0?"male":"female",g=goals[goal.getSelectedItemPosition()];if(!WellnessMath.valid(a,h,w,sx,ac,g)){notice("Use age 14–90, height 80–250 cm and weight 20–350 kg.");return;}store.put("profile",json("age",a,"height",h,"weight",w,"sex",sx,"activity",ac,"goal",g));JSONObject settings=object(state(),"ngPersonalSettings"),targets=object(settings,"targets");targets.remove("protein");try{settings.put("targets",targets);}catch(Exception ignored){}store.put("ngPersonalSettings",settings);tab="Home";render();saved();});
        addButton("Back to Home",()->{tab="Home";render();});
    }
    private void customTargets(){body.removeAllViews();heading("Your daily targets","Choose your own targets or restore profile estimates.");EditText cal=input("Calories (1200–5000)",String.valueOf(calories()),true),p=input("Protein grams (20–300)",String.valueOf(protein()),true);addButton("Save targets",()->{double c=number(cal.getText().toString()),g=number(p.getText().toString());if(!Double.isFinite(c)||c<1200||c>5000||!Double.isFinite(g)||g<20||g>300){notice("Use 1200–5000 kcal and 20–300 g protein.");return;}JSONObject settings=object(state(),"ngPersonalSettings");try{settings.put("targets",json("calories",c,"protein",g));}catch(Exception ignored){}store.put("ngPersonalSettings",settings);store.put("proteinTarget",g);render();saved();});addButton("Use profile targets",()->{JSONObject settings=object(state(),"ngPersonalSettings");settings.remove("targets");store.put("ngPersonalSettings",settings);store.put("proteinTarget",protein());render();saved();});}
    private void food(){
        heading("Food studio","Search Indian foods, log a serving or add your own nutrition. Values are approximate.");
        AutoCompleteTextView search=new AutoCompleteTextView(this);search.setHint("Search Indian foods");search.setSingleLine(true);search.setThreshold(1);search.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_dropdown_item_1line,FoodCatalog.NAMES));body.addView(search,new LinearLayout.LayoutParams(-1,dp(56)));
        EditText qty=input("Serving (grams)","100",true);addButton("Log food",()->{int index=FoodCatalog.find(search.getText().toString());double grams=number(qty.getText().toString());if(index<0){notice("Choose a catalogue food, or use Add custom food.");return;}if(!Double.isFinite(grams)||grams<=0||grams>5000){notice("Enter 1–5,000 grams.");return;}double[] n=FoodCatalog.NUTRIENTS[index];logFood(FoodCatalog.NAMES[index],grams,n[0]*grams/100,n[1]*grams/100,n[2]*grams/100,n[3]*grams/100,n[4]*grams/100);});addButton("Add custom food",this::customFood);
        double[] t=totals(day());card("Today's nutrition",fmt(t[0])+" kcal • "+fmt(t[1])+" g protein\n"+fmt(t[2])+" g carbs • "+fmt(t[3])+" g fat • "+fmt(t[4])+" g fibre");
        JSONArray logs=array(state(),"nutritionLog");boolean found=false;for(int i=logs.length()-1;i>=0;i--){JSONObject x=logs.optJSONObject(i);if(x==null||!day().equals(x.optString("date")))continue;found=true;final int at=i;card(x.optString("name")+" · "+fmt(x.optDouble("qty",100))+" g",fmt(x.optDouble("cal"))+" kcal • "+fmt(x.optDouble("p"))+" g protein");addButton("Remove "+x.optString("name"),()->new AlertDialog.Builder(this).setMessage("Remove this food log?").setPositiveButton("Remove",(d,w)->{JSONArray current=array(state(),"nutritionLog");current.remove(at);store.put("nutritionLog",current);render();saved();}).setNegativeButton("Cancel",null).show());}if(!found)label("No foods logged today.");
    }
    private void customFood(){body.removeAllViews();heading("Add your food","Enter nutrition for the serving you ate, using the label or your estimate.");EditText name=input("Food name","",false),grams=input("Serving grams","100",true),cal=input("Serving calories","",true),p=input("Serving protein grams","",true),c=input("Serving carbs grams","",true),fat=input("Serving fat grams","",true),f=input("Serving fibre grams","",true);addButton("Save custom food",()->{String n=name.getText().toString().trim();double g=number(grams.getText().toString());EditText[] fields={cal,p,c,fat,f};double[] v=new double[5];for(int i=0;i<5;i++){String value=fields[i].getText().toString();v[i]=value.isEmpty()?0:number(value);if(!Double.isFinite(v[i])||v[i]<0||v[i]>10000){notice("Enter non-negative nutrition values within 10,000.");return;}}if(n.isEmpty()||n.length()>160||!Double.isFinite(g)||g<=0||g>5000||v[0]<=0){notice("Enter a food name, serving up to 5,000 g and positive calories.");return;}logFood(n,g,v[0],v[1],v[2],v[3],v[4]);});addButton("Back to Food",this::render);}
    private void logFood(String name,double grams,double cal,double p,double c,double fat,double fibre){JSONArray logs=array(state(),"nutritionLog");logs.put(json("name",name,"qty",grams,"cal",cal,"p",p,"c",c,"fat",fat,"f",fibre,"date",day(),"emoji","🥗"));store.put("nutritionLog",logs);store.put("foodLogs",state().optInt("foodLogs",0)+1);tab="Food";render();saved();}
    private long activeSeconds(){return accumulated+(running?(SystemClock.elapsedRealtime()-startedAt)/1000:0);}
    private void pauseTimer(){if(running){accumulated=activeSeconds();running=false;}}
    private String time(long seconds){return String.format(Locale.ROOT,"%02d:%02d",seconds/60,seconds%60);}
    private void move(){heading("Move with your guide","Native instructions and an active-time timer. Stop if you feel pain; take rest whenever needed.");label("Choose a movement");Spinner exercise=spinner(EXERCISES,selectedExercise);addButton("Show exercise steps",()->{if(running||accumulated>0){notice("Finish or discard your current session before changing exercise.");return;}selectedExercise=exercise.getSelectedItemPosition();render();});card(EXERCISES[selectedExercise],CUES[selectedExercise]);timerText=text(time(activeSeconds())+(running?" • active":" • paused"),30,GREEN);body.addView(timerText);addButton(running?"Pause session":"Start / resume session",()->{if(running)pauseTimer();else{startedAt=SystemClock.elapsedRealtime();running=true;}render();});addButton("Finish and save session",()->{pauseTimer();long seconds=accumulated;if(seconds<1){notice("Start the timer before saving activity.");return;}JSONArray history=array(state(),"ngTrainerHistory");history.put(json("date",Instant.now().toString(),"goal",EXERCISES[selectedExercise],"setting","home","duration",Math.max(1,seconds/60),"actualSeconds",seconds));store.put("ngTrainerHistory",history);store.put("exerciseLogs",state().optInt("exerciseLogs",0)+1);accumulated=0;render();notice(seconds>=60?"Session saved. Great consistency.":"Partial activity saved; a completed-session habit requires at least one active minute.");});addButton("Discard timer",()->new AlertDialog.Builder(this).setMessage("Discard the current timer?").setPositiveButton("Discard",(d,w)->{pauseTimer();accumulated=0;render();}).setNegativeButton("Cancel",null).show());
        JSONArray history=array(state(),"ngTrainerHistory");for(int i=history.length()-1;i>=Math.max(0,history.length()-5);i--){JSONObject x=history.optJSONObject(i);if(x!=null)card(x.optString("goal","Workout"),fmt(x.optDouble("actualSeconds",0)/60)+" active minutes • "+x.optString("date").split("T")[0]);}}
    private void journey(){heading("Your journey","Recovery and reflection belong beside food and movement.");JSONObject current=null;JSONArray recovery=array(state(),"ngMeasurements");for(int i=0;i<recovery.length();i++)if(recovery.optJSONObject(i)!=null&&day().equals(recovery.optJSONObject(i).optString("date")))current=recovery.optJSONObject(i);EditText sleep=input("Sleep hours",current==null?"":current.optString("sleep",""),true);label("Mood");Spinner mood=spinner(new String[]{"good","okay","low"},current==null?0:current.optString("mood").equals("okay")?1:current.optString("mood").equals("low")?2:0);label("Stress (1 calm – 5 high)");Spinner stress=spinner(new String[]{"1","2","3","4","5"},current==null?2:Math.max(0,Math.min(4,current.optInt("stress",3)-1)));EditText reflection=input("A small win or reflection","",false);addButton("Save recovery",()->{double hours=number(sleep.getText().toString());if(!Double.isFinite(hours)||hours<0||hours>24){notice("Enter 0–24 hours of sleep.");return;}JSONArray list=array(state(),"ngMeasurements");JSONObject previous=new JSONObject();for(int i=list.length()-1;i>=0;i--)if(list.optJSONObject(i)!=null&&day().equals(list.optJSONObject(i).optString("date"))){previous=list.optJSONObject(i);list.remove(i);}try{previous.put("date",day()).put("sleep",hours).put("mood",mood.getSelectedItem().toString()).put("stress",stress.getSelectedItemPosition()+1);}catch(Exception ignored){}list.put(previous);store.put("ngMeasurements",list);JSONObject habits=object(state(),"ngHabits");try{habits.put(day(),previous);}catch(Exception ignored){}store.put("ngHabits",habits);String note=reflection.getText().toString().trim();if(!note.isEmpty()){JSONArray journal=array(state(),"journal");journal.put(json("date",Instant.now().toString(),"text",note.substring(0,Math.min(1000,note.length()))));store.put("journal",journal);}render();saved();});for(int i=recovery.length()-1;i>=Math.max(0,recovery.length()-7);i--){JSONObject r=recovery.optJSONObject(i);if(r!=null)card(r.optString("date"),r.optString("sleep")+" h sleep • "+r.optString("mood"));}JSONArray journal=array(state(),"journal");for(int i=journal.length()-1;i>=Math.max(0,journal.length()-5);i--){JSONObject x=journal.optJSONObject(i);if(x!=null)card("Reflection",x.optString("text"));}}
    private void reports(){heading("This week","Real logs from the last seven days. Suggestions are not counted as completed activity.");JSONArray exercise=array(state(),"ngTrainerHistory"),recovery=array(state(),"ngMeasurements");for(int i=0;i<7;i++){String date=LocalDate.now().minusDays(i).toString();double[] t=totals(date);int workouts=0;for(int j=0;j<exercise.length();j++){JSONObject x=exercise.optJSONObject(j);if(x!=null&&date.equals(localDate(x.optString("date")))&&x.optInt("actualSeconds")>=60)workouts++;}boolean recovered=false;for(int j=0;j<recovery.length();j++)if(recovery.optJSONObject(j)!=null&&date.equals(recovery.optJSONObject(j).optString("date")))recovered=true;card(date,fmt(t[0])+" kcal • "+fmt(t[1])+" g protein\n"+workouts+" completed sessions • recovery "+(recovered?"logged":"not logged"));}addButton("Export food CSV",()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"NutriGuide-food-log.csv");try{startActivityForResult(intent,80);}catch(android.content.ActivityNotFoundException e){notice("No document provider is available on this device.");}});if(store.signedIn())addButton("Sync my account",this::sync);else addButton("Sign in for cloud sync",()->showAccount(false));label("Native camera/photo logging, wearable sync, background reminders and automatic meal planning are not included in this first native build.");}
    private String localDate(String value){try{return Instant.parse(value).atZone(ZoneId.systemDefault()).toLocalDate().toString();}catch(Exception e){return value.split("T")[0];}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==80&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new Exception();StringBuilder csv=new StringBuilder("Date,Food,Grams,Calories,Protein,Carbs,Fat,Fibre\n");JSONArray list=array(state(),"nutritionLog");for(int i=0;i<list.length();i++){JSONObject x=list.optJSONObject(i);if(x==null)continue;csv.append(cell(x.optString("date"))).append(',').append(cell(x.optString("name"))).append(',').append(x.optDouble("qty",0)).append(',').append(x.optDouble("cal",0)).append(',').append(x.optDouble("p",0)).append(',').append(x.optDouble("c",0)).append(',').append(x.optDouble("fat",0)).append(',').append(x.optDouble("f",0)).append('\n');}out.write(csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));notice("Food log exported.");}catch(Exception e){notice("The export could not be saved.");}}}
    private String cell(String value){if(value.matches("^[=+@\\-].*"))value="'"+value;return "\""+value.replace("\"","\"\"")+"\"";}
    private void showAccount(boolean signup){
        body.removeAllViews();heading(store.signedIn()?"Your account":signup?"Create an account":"Sign in",store.signedIn()?store.email():"Native email/password sign-in. On-device mode works without an account.");
        if(store.signedIn()){addButton("Sync now",this::sync);addButton("Sign out on this device",()->{if(busy){notice("Wait for the current request to finish.");return;}busy=true;worker.execute(()->{try{api.request("/api/account/logout",new JSONObject());}catch(Exception ignored){}api.clear();runOnUiThread(()->{busy=false;store.switchOwner("guest","");tab="Home";render();notice("Signed out locally. Guest and account data remain separate.");});});});addButton("Back to Home",()->{tab="Home";render();});return;}
        EditText name=signup?input("Full name","",false):null,email=input("Email","",false),password=input("Password","",false);email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);EditText confirm=signup?input("Confirm password","",false):null;if(confirm!=null)confirm.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
        addButton(signup?"Create account":"Sign in",()->{String mail=email.getText().toString().trim(),pass=password.getText().toString();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(mail).matches()||pass.isEmpty()){notice("Enter a valid email and password.");return;}if(signup&&(name.getText().toString().trim().isEmpty()||pass.length()<12||pass.length()>128||!pass.equals(confirm.getText().toString()))){notice("Use your name and matching passwords of 12–128 characters.");return;}JSONObject payload=json("email",mail,"password",pass);if(signup)try{payload.put("name",name.getText().toString().trim()).put("confirmPassword",confirm.getText().toString());}catch(Exception ignored){}run(()->{api.clear();JSONObject response=api.request(signup?"/api/account/sign-up":"/api/account/sign-in",payload);if(signup)return response;JSONObject me=api.request("/api/me",null),user=me.optJSONObject("user");if(!me.optBoolean("authenticated")||user==null||user.optString("id").isEmpty())throw new Exception("Could not verify this account.");JSONObject remote=api.request("/api/state",null);return json("user",user,"state",remote.getJSONObject("state"));},response->{password.setText("");if(confirm!=null)confirm.setText("");if(signup){notice("Check your email to confirm the account, then return here and sign in. Email-link acceptance still needs live verification.");}else{JSONObject user=response.optJSONObject("user");store.switchOwner(user.optString("id"),user.optString("email"));try{store.hydrate(response.getJSONObject("state"));}catch(Exception e){notice("Signed in, but account data could not be loaded.");return;}tab="Home";render();notice("Signed in. Guest data was not copied into your account.");}});});
        addButton(signup?"Already registered? Sign in":"Create a new account",()->showAccount(!signup));addButton("Continue on this device",()->{tab="Home";render();});label("Confirm signup in your email, then return to this app. Connected ChatGPT login and native recovery links are not yet supported.");
    }
    private interface Task{JSONObject execute() throws Exception;}
    private interface Done{void accept(JSONObject result);}
    private void run(Task task,Done done){if(busy){notice("Wait for the current request to finish.");return;}busy=true;notice("Connecting securely…");worker.execute(()->{try{JSONObject result=task.execute();runOnUiThread(()->{busy=false;if(!isFinishing()&&!isDestroyed())done.accept(result);});}catch(Exception e){runOnUiThread(()->{busy=false;if(!isFinishing()&&!isDestroyed())notice(e.getMessage()==null?"Connection unavailable. On-device data was kept.":e.getMessage());});}});}
    private void sync(){if(!store.signedIn()){notice("Sign in to sync. Guest data stays on this phone.");return;}String owner=store.owner();long revision=store.revision();JSONObject patch=store.patch();run(()->{JSONObject me=api.request("/api/me",null);if(!me.optBoolean("authenticated")||!owner.equals(object(me,"user").optString("id")))throw new Exception("Sign in again to sync this account. Local records were kept.");JSONObject remote=api.request("/api/state",null).getJSONObject("state"),merged=StateMerge.merge(remote,patch);if(patch.length()>0)api.request("/api/state",json("state",merged));return merged;},merged->{if(!owner.equals(store.owner()))return;store.acknowledge(merged,revision);render();notice(store.patch().length()==0?"Cloud synced for "+store.email():"Snapshot synced; newer on-device changes still need Sync.");});}
    private void heading(String title,String subtitle){TextView t=text(title,26,INK);t.setTypeface(null,Typeface.BOLD);body.addView(t);body.addView(text(subtitle,14,MUTED));}
    private void label(String value){body.addView(text(value,14,MUTED));}
    private void card(String title,String detail){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(16),dp(14),dp(16),dp(10));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(18));bg.setStroke(dp(1),0xffd8e7df);card.setBackground(bg);TextView heading=text(title,17,INK);heading.setTypeface(null,Typeface.BOLD);card.addView(heading);card.addView(text(detail,15,MUTED));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(8));body.addView(card,p);}
    private EditText input(String hint,String value,boolean numeric){EditText e=new EditText(this);e.setHint(hint);e.setContentDescription(hint);e.setText(value);e.setTextSize(16);e.setSingleLine(true);if(numeric)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);body.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));return e;}
    private Spinner spinner(String[] values,int selected){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,values);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);s.setSelection(selected);body.addView(s,new LinearLayout.LayoutParams(-1,dp(52)));return s;}
    private Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(GREEN));b.setOnClickListener(v->action.run());return b;}
    private void addButton(String name,Runnable action){Button b=button(name,action);body.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(8));return t;}
    private void notice(String value){status.setText(value);}
    private void saved(){notice(store.signedIn()?"Saved on this phone. Tap Sync to update your cloud account.":"Saved on this phone • on-device mode.");}
    private String fmt(double n){return String.format(Locale.ROOT,"%.1f",n);}
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
}
